{
  "query": "SELECT Producer__c, Producer__r.Name, COUNT(Id) cnt, SUM(Annual_Premium__c) prem FROM Policy__c WHERE Status__c IN ('Active','Pending Renewal') GROUP BY Producer__c, Producer__r.Name ORDER BY COUNT(Id) DESC LIMIT 5"
}

