  "query": "SELECT Producer__r.Name, Line_of_Business__c, COUNT(Id) cnt, SUM(Annual_Premium__c) prem FROM Policy__c WHERE Status__c IN ('Active','Pending Renewal') AND Line_of_Business__c LIKE '%Workers%' GROUP BY Producer__r.Name, Line_of_Business__c"
}
